package com.jinloes.practice;
import java.util.*;
public class Solution { record Entry(int value,int list,int index){} public static int[] smallestRange(List<List<Integer>> lists){ PriorityQueue<Entry> heap=new PriorityQueue<>(Comparator.comparingInt(Entry::value)); int max=Integer.MIN_VALUE; for(int i=0;i<lists.size();i++){ int v=lists.get(i).get(0); heap.add(new Entry(v,i,0)); max=Math.max(max,v); } int bestLow=heap.peek().value(), bestHigh=max; while(heap.size()==lists.size()){ Entry min=heap.poll(); if(max-min.value()<bestHigh-bestLow || (max-min.value()==bestHigh-bestLow && min.value()<bestLow)){ bestLow=min.value(); bestHigh=max; } int nextIndex=min.index()+1; if(nextIndex==lists.get(min.list()).size()) break; int next=lists.get(min.list()).get(nextIndex); heap.add(new Entry(next,min.list(),nextIndex)); max=Math.max(max,next); } return new int[]{bestLow,bestHigh}; } }
